use std::collections::BinaryHeap;

let mut heap = BinaryHeap::<u32>::from([1, 2, 3, 4, 5, 6, 7]);

unsafe {
    for value in heap.as_mut_slice() {
        *value = (*value).saturating_mul(2);
    }
}
