fn unsound_transmute<T>(val: &mut T) -> &mut MaybeUninit<T> {
    unsafe { core::mem::transmute(val) }
}

fn main() {
    let mut code = 0;
    let code = &mut code;
    let code2 = unsound_transmute(code);
    *code2 = MaybeUninit::uninit();
    std::process::exit(*code); // UB! Accessing uninitialized memory.
