#[repr(C)] struct T(MaybeUninit<[u8; 4]>);
#[repr(C)] struct U(u8, u16);
fn non_identity(t: T) -> T {
    unsafe {
        // May lose an initialized byte.
        let u: MaybeUninit<U> = transmute(t);
        transmute(u)
    }
}
```

